package pl.zagranietyper.parser;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class FootballTeamFirstGoalSyntaxAdapterTest {private final FootballTeamFirstGoalSyntaxAdapter p=new FootballTeamFirstGoalSyntaxAdapter();@Test void consumesAuditedTeamForms(){assertEquals(FootballTeamFirstGoalSyntaxAdapter.Side.AWAY,p.parse("Pierwszy gol: Udinese","Bologna","Udinese").side());assertEquals(FootballTeamFirstGoalSyntaxAdapter.Side.HOME,p.parse("Pierwszy gol dla Lechii","Lechia Gdansk","Radomiak Radom").side());assertEquals(FootballTeamFirstGoalSyntaxAdapter.Side.AWAY,p.parse("1. gol: 2","Roma","Milan").side());assertEquals(FootballTeamFirstGoalSyntaxAdapter.Side.HOME,p.parse("1. gol w meczu - Fulham","Fulham","Chelsea").side());}@Test void rejectsUnsafeOrUnresolved(){assertFalse(p.parse("Pierwszy gol: Kolumbia","Colombia","Brazil").parsed());assertFalse(p.parse("Pierwszy gol: Harry Kane","Bayern München","Mainz").parsed());assertFalse(p.parse("Pierwszy gol: Lille (w 1. połowie)","Lille","Monaco").parsed());assertFalse(p.parse("Pierwszy gol do 30 min: Lille","Lille","Monaco").parsed());assertFalse(p.parse("Pierwszy gol: Lille i powyżej 2.5","Lille","Monaco").parsed());}}
